//! INTLCLDR (LEDGER SR137): the IANA time zone database 2025b as data. `zones.rs` is generated by
//! `tools/gen_tz.py` (zic -b fat over eggert/tz 2025b): every Zone's transitions up to 2037 and the POSIX rule
//! after them, plus every Link. This module finds identifiers and decodes a zone's transitions.

mod zones;

use alloc::vec::Vec;
pub use zones::{Link, Zone, LINKS, TZ_VERSION, ZONES};

/// A resolved time zone identifier.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct Found {
    /// The identifier as the database spells it (the request, case-normalized).
    pub id: &'static str,
    /// The primary identifier (ECMA-262 §21.4.1.20): the Zone, or a Link that names a zone of its own country.
    pub primary_id: &'static str,
    /// A number naming the primary identifier: a Zone's index, or `ZONES.len() +` a primary Link's index.
    pub primary: u16,
    /// The Zone whose data applies (index into `ZONES`).
    pub data: u16,
}

fn link_found(i: usize) -> Found {
    let l = &LINKS[i];
    let target = &ZONES[l.target as usize];
    if l.primary {
        Found { id: l.id, primary_id: l.id, primary: (ZONES.len() + i) as u16, data: l.target }
    } else {
        Found { id: l.id, primary_id: target.id, primary: l.target, data: l.target }
    }
}

/// Look an IANA identifier up, ASCII case-insensitively (GetAvailableNamedTimeZoneIdentifier).
pub fn find(id: &str) -> Option<Found> {
    if let Some(i) = ZONES.iter().position(|z| z.id.eq_ignore_ascii_case(id)) {
        let z = &ZONES[i];
        return Some(Found { id: z.id, primary_id: z.id, primary: i as u16, data: i as u16 });
    }
    LINKS.iter().position(|l| l.id.eq_ignore_ascii_case(id)).map(link_found)
}

/// The Found record of a primary number (the inverse of `Found::primary`).
pub fn by_primary(p: u16) -> Found {
    let p = p as usize;
    if p < ZONES.len() {
        let z = &ZONES[p];
        Found { id: z.id, primary_id: z.id, primary: p as u16, data: p as u16 }
    } else {
        link_found(p - ZONES.len())
    }
}

/// Every primary identifier (Zones and primary Links), sorted — AvailableNamedTimeZoneIdentifiers.
pub fn primary_ids() -> Vec<&'static str> {
    let mut v: Vec<&'static str> = ZONES.iter().map(|z| z.id).filter(|id| !id.starts_with("Etc/") && *id != "Factory").collect();
    v.extend(LINKS.iter().filter(|l| l.primary).map(|l| l.id));
    v.sort_unstable();
    v
}

/// The other names (Links) of a Zone — the ids CLDR may file its data under.
pub fn aliases_of(data: u16) -> impl Iterator<Item = &'static str> {
    LINKS.iter().filter(move |l| l.target == data).map(|l| l.id)
}

/// One local time type: UTC offset in seconds and the daylight-saving flag.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct Kind {
    pub offset: i32,
    pub dst: bool,
}

fn kind(v: i32) -> Kind {
    Kind { offset: v.div_euclid(2), dst: v.rem_euclid(2) == 1 }
}

/// The type in effect before the first transition.
pub fn initial(data: u16) -> Kind {
    kind(ZONES[data as usize].types[0])
}

/// Every transition of a zone: (instant in epoch seconds, the type from then on), ascending.
pub fn transitions(data: u16) -> Vec<(i64, Kind)> {
    let z = &ZONES[data as usize];
    let mut out = Vec::new();
    let mut t: i64 = 0;
    let mut i = 0;
    while i < z.data.len() {
        let mut v: u64 = 0;
        let mut shift = 0;
        loop {
            let b = z.data[i];
            i += 1;
            v |= ((b & 0x7f) as u64) << shift;
            shift += 7;
            if b & 0x80 == 0 {
                break;
            }
        }
        t += ((v >> 1) as i64) ^ -((v & 1) as i64);
        let k = kind(z.types[z.data[i] as usize]);
        i += 1;
        out.push((t, k));
    }
    out
}

/// The explicit-table type at epoch second `t`, or None at or after the last transition (the POSIX rule's range).
pub fn kind_at(data: u16, t: i64) -> Option<Kind> {
    let z = &ZONES[data as usize];
    let mut cur = kind(z.types[0]);
    let mut tt: i64 = 0;
    let mut i = 0;
    while i < z.data.len() {
        let mut v: u64 = 0;
        let mut shift = 0;
        loop {
            let b = z.data[i];
            i += 1;
            v |= ((b & 0x7f) as u64) << shift;
            shift += 7;
            if b & 0x80 == 0 {
                break;
            }
        }
        tt += ((v >> 1) as i64) ^ -((v & 1) as i64);
        if tt > t {
            return Some(cur);
        }
        cur = kind(z.types[z.data[i] as usize]);
        i += 1;
    }
    if z.data.is_empty() { Some(cur) } else { None }
}

/// The instant of the last explicit transition (None for a zone without transitions).
pub fn last_transition(data: u16) -> Option<i64> {
    transitions(data).last().map(|x| x.0)
}
